mapper.update:
update survey_task_type
set survey_id = #{surveyId,jdbcType=BIGINT},
  survey_info_id = #{surveyInfoId,jdbcType=BIGINT},
  task_id = #{taskId,jdbcType=BIGINT},
  task_name = #{taskName,jdbcType=VARCHAR}
where id = #{id,jdbcType=BIGINT}

mapper.select:
SELECT stt.task_id, stt.task_name FROM survey_task_type stt
  where stt.task_id in
    (
        SELECT sict.task_id FROM survey_investigator_case_type sict
        LEFT JOIN survey_investigator_case sic on sict.survey_user_case_id = sic.id
        where sic.survey_info_id = #{surveyInfoId,jdbcType=BIGINT} and sic.survey_user_id = #{surveyUserId,jdbcType=BIGINT}
    )
  and stt.survey_info_id = #{surveyInfoId,jdbcType=BIGINT};
